def match(pattern: str, text: str) -> bool:
    """
    Implements basic regex matching using recursion and memoization. 
    Supports literal characters, '.', '*', and '+' operators.
    """

    def is_match(p_idx: int, t_idx: int, memo: dict) -> bool:
        if (p_idx, t_idx) in memo:
            return memo[(p_idx, t_idx)]

        if p_idx == len(pattern) and t_idx == len(text):
            return True
        if p_idx == len(pattern):
            return False

        first_match = (t_idx < len(text)) and (pattern[p_idx] in {text[t_idx], '.'})

        if (p_idx + 1) < len(pattern):
            if pattern[p_idx + 1] == '*':
                memo[(p_idx, t_idx)] = (is_match(p_idx + 2, t_idx, memo) or 
                                         (first_match and is_match(p_idx, t_idx + 1, memo)))
                return memo[(p_idx, t_idx)]
            elif pattern[p_idx + 1] == '+':
                if first_match:
                    memo[(p_idx, t_idx)] = is_match(p_idx, t_idx + 1, memo) or is_match(p_idx + 2, t_idx, memo)
                    return memo[(p_idx, t_idx)]

        memo[(p_idx, t_idx)] = first_match and is_match(p_idx + 1, t_idx + 1, memo)
        return memo[(p_idx, t_idx)]

    return is_match(0, 0, {})

