def match(pattern: str, text: str) -> bool:
    """
    Implements basic regex matching using an iterative dynamic programming approach. 
    Supports literal characters, '.', '*', and '+' operators.
    """

    dp = [[False] * (len(text) + 1) for _ in range(len(pattern) + 1)]
    dp[0][0] = True

    for i in range(1, len(pattern) + 1):
        if pattern[i - 1] == '*':
            dp[i][0] = dp[i - 2][0]

    for i in range(1, len(pattern) + 1):
        for j in range(1, len(text) + 1):
            if pattern[i - 1] == text[j - 1] or pattern[i - 1] == '.':
                dp[i][j] = dp[i - 1][j - 1]
            elif pattern[i - 1] == '*':
                dp[i][j] = dp[i - 2][j] or (dp[i][j - 1] and 
                                             (text[j - 1] == pattern[i - 2] or pattern[i - 2] == '.'))
            elif pattern[i - 1] == '+':
                dp[i][j] = (dp[i - 1][j - 1] or 
                             (dp[i][j - 1] and 
                              (text[j - 1] == pattern[i - 2] or pattern[i - 2] == '.')))

    return dp[len(pattern)][len(text)]

def match(pattern: str, text: str) -> bool:
    """
    Implements basic regex matching using a recursive backtracking algorithm.
    Supports literal characters, '.', '*' and '+' operators.
    """

    def backtrack(p_index: int, t_index: int) -> bool:
        if p_index == len(pattern) and t_index == len(text):
            return True
        if p_index < len(pattern) and t_index < len(text) and (pattern[p_index] == text[t_index] or pattern[p_index] == '.'):
            return backtrack(p_index + 1, t_index + 1)

        if p_index < len(pattern):
            if pattern[p_index] == '*':
                return backtrack(p_index - 1, t_index) or (t_index < len(text) and backtrack(p_index, t_index + 1))
            elif pattern[p_index] == '+':
                return (t_index < len(text) and 
                        (backtrack(p_index - 1, t_index + 1) or 
                         (backtrack(p_index, t_index + 1) if 
                          text[t_index] == pattern[p_index - 1] or pattern[p_index - 1] == '.' else False)))

        return False

    return backtrack(0, 0)
